// CSD_RATIONALE_BEGIN
// Root-cause analysis of prior failures:
// 1. 25/49 examples: model never emitted << (900-token budget consumed by reasoning).
//    Fix: after a 75%-budget prefix window, force OpenConstrainedSpan so every
//    example is guaranteed a << >> span.
// 2. 21/49 examples: spans had avg 1.57 tokens (<<n>>, <<2>>, <<total>>).
//    Root cause: CloseSpanIfComplete was called after every single constrained token;
//    the math expression parser accepts any identifier or number as a complete expression,
//    so the span closed immediately after the first token.
//    Fix: require at least minExpr=5 constrained tokens before any CloseSpanIfComplete check.
// 3. Prior "best result" Phase 4 used forbidden next=="<<" literal comparison.
//    Fix: use RenderedEndsWith(generated, "<<") throughout.
// 4. Multi-phase nested loops caused Dafny SMT explosion.
//    Fix: exactly 2 flat while loops (Phase 1 unconstrained, Phase 3 constrained)
//    each with a single-variable decreases clause.
// Structure:
//   Phase 1: UnconstrainedStep loop (up to 75% budget) watching for << via RenderedEndsWith.
//   Phase 2: If still not in a span, force OpenConstrainedSpan.
//   Phase 3: Constrained loop — first minExpr iterations: ConstrainedStep only (no close check);
//            remaining iterations: CloseSpanIfComplete then ConstrainedStep if not closed.
//   Phase 4: CloseSpanWithinBudget on any still-open span.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// 1. parser_validity (insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)):
//   Phase 1: EnterObservedConstrainedSpan sets currentConstrainedOut := [], valid by precondition.
//     When << not yet seen, insideConstrainedOut stays false (implication vacuously true).
//   Phase 2: OpenConstrainedSpan sets currentConstrainedOut := [], valid by precondition.
//   Phase 3, exprCount < minExpr branch: ConstrainedStep returns EOS or a parser-valid token;
//     AppendConstrainedToken appends only the parser-valid token, preserving IsValidPrefix.
//     EOS breaks without append, leaving invariant intact.
//   Phase 3, exprCount >= minExpr, closed=true: CloseSpanIfComplete sets insideConstrainedOut
//     to false and currentConstrainedOut to [], making implication vacuously true.
//   Phase 3, exprCount >= minExpr, closed=false: CloseSpanIfComplete is +0 cost and leaves
//     state unchanged; subsequent ConstrainedStep + AppendConstrainedToken preserves validity.
//   Phase 4: CloseSpanWithinBudget postcondition guarantees insideOut ==> parser.IsValidPrefix(currentOut).
//
// 2. progress (|generated| <= |generatedPrefix| + steps):
//   Phase 1: each iteration steps += 1 and generated grows by at most 1 (EOS: no append).
//     EnterObservedConstrainedSpan is +0 tokens and leaves generated unchanged.
//   Phase 2: OpenConstrainedSpan appends exactly one token (<<) and steps += 1, preserving bound.
//   Phase 3: each iteration takes exactly one constrained step (+1 step) in both branches.
//     AppendConstrainedToken appends exactly 1 token (EOS path breaks without append, still +1 step).
//     CloseSpanIfComplete when closed appends >> (1 token) and steps += 1 then breaks.
//     CloseSpanIfComplete when not closed is +0 tokens and +0 steps (step comes from ConstrainedStep).
//     So steps grows by 1 and generated grows by at most 1 each iteration.
//   Phase 4: CloseSpanWithinBudget with budget cb satisfies |generatedOut| <= |generated| + cb
//     and cost <= old(cost) + cb. We set steps := steps + cb, so
//     |generatedOut| <= |generatedPrefix| + steps_before + cb = |generatedPrefix| + steps_after. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm, "Solve step by step. When you have the final answer write: The answer is <<EXPR>> where EXPR is an arithmetic expression using the variable names from the problem and operators +, -, *, /, (, ). No LaTeX, no curly braces, no backslashes. Keep the expression short. Example: The answer is <<n * price - discount>>");

var steps: nat := 0;

// Prefix budget: allow up to 75% of maxSteps for unconstrained reasoning
var prefixLimit: nat := (maxSteps / 4) * 3;
if prefixLimit == 0 && maxSteps > 0 { prefixLimit := maxSteps; }

// Phase 1: Unconstrained generation watching for << via RenderedEndsWith
while steps < prefixLimit && !insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases prefixLimit - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next == eosToken {
    break;
  }
  generated := generated + [next];
  if RenderedEndsWith(generated, "<<") {
    var eg, ei, ec := helpers.EnterObservedConstrainedSpan(lm, generated);
    generated := eg;
    insideConstrainedOut := ei;
    currentConstrainedOut := ec;
  }
}

// Phase 2: If no << detected naturally, force open a constrained span
if !insideConstrainedOut && steps < maxSteps {
  var fg, fi, fc := helpers.OpenConstrainedSpan(lm, generated);
  generated := fg;
  insideConstrainedOut := fi;
  currentConstrainedOut := fc;
