  if exprCount >= minExpr {
    // Try to close if the expression is parseable as complete
    var cg2, ci2, cc2, closed2 := helpers.CloseSpanIfComplete(lm, parser, generated, currentConstrainedOut);
    if closed2 {
      generated := cg2;
      insideConstrainedOut := ci2;
      currentConstrainedOut := cc2;
      steps := steps + 1;
      break;
    }
    // Not closed: +0 cost; fall through to constrained step
    var cp := prompt + generated[..|generated| - |currentConstrainedOut|];
    var nx := helpers.ConstrainedStep(lm, parser, cp, currentConstrainedOut, eosToken);
    steps := steps + 1;
    exprCount := exprCount + 1;
    if nx == eosToken {
      break;
    }
    var ag, ai, ac := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, nx);
    generated := ag;
    insideConstrainedOut := ai;
    currentConstrainedOut := ac;
  } else {
    // Below minimum token floor: just generate, no close check yet
    var cp2 := prompt + generated[..|generated| - |currentConstrainedOut|];
    var nx2 := helpers.ConstrainedStep(lm, parser, cp2, currentConstrainedOut, eosToken);
    steps := steps + 1;
    exprCount := exprCount + 1;
    if nx2 == eosToken {
      break;
    }
    var ag2, ai2, ac2 := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, nx2);
    generated := ag2;
    insideConstrainedOut := ai2;
    currentConstrainedOut := ac2;
  }
}

// Phase 4: If span still open, reliably close it within remaining budget
if insideConstrainedOut && steps < maxSteps {
  var cb: nat := maxSteps - steps;
  if cb > 50 { cb := 50; }
  var wg, wi, wc := helpers.CloseSpanWithinBudget(lm, parser, prompt, generated, currentConstrainedOut, eosToken, cb);
  generated := wg;
  insideConstrainedOut := wi;
  currentConstrainedOut := wc;
  steps := steps + cb;
}

